input.command:
cd /tmp/lnav-mgmt-9x7q && mkdir -p fmtdir/formats/installed goodfmt badfmt badjson && cat > goodfmt/mytest_log.json <<'EOF'
{
    "$schema": "https://lnav.org/schemas/format-v1.schema.json",
    "mytest_log": {
        "title": "My Test Log",
        "description": "A test format for probing lnav",
        "url": "https://example.com/",
        "regex": {
            "std": {
                "pattern": "^(?<timestamp>\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}) (?<level>\\w+) (?<body>.*)$"
            }
        },
        "level-field": "level",
        "level": {
            "error": "ERROR",
            "warning": "WARN",
            "info": "INFO"
        },
        "value": {
            "level": { "kind": "string" }
        },
        "sample": [
            { "line": "2023-01-01 12:00:00 INFO hello world" }
        ]
    }
}
EOF
echo ok; cat > badfmt/broken_log.json <<'EOF'
{
    "$schema": "https://lnav.org/schemas/format-v1.schema.json",
    "broken_log": {
        "title": "Broken",
        "regex": {
            "std": {
                "pattern": "^(?<timestamp>\\d+) (?<body>.*$"
            }
        },
        "sample": [
            { "line": "12345 hello" }
        ]
    }
}
EOF
echo ok2; printf '{ this is not json at all\n' > badjson/notjson.json; echo ok3; ls -R /tmp/lnav-mgmt-9x7q/goodfmt /tmp/lnav-mgmt-9x7q/badfmt /tmp/lnav-mgmt-9x7q/badjson

cd /tmp/lnav-mgmt-9x7q && mkdir -p warndir/formats/installed && cat > warndir/formats/installed/warn_log.json <<'EOF'
{
    "$schema": "https://lnav.org/schemas/format-v1.schema.json",
    "warn_log": {
        "title": "Warn",
        "bogus-property": true,
        "regex": {
            "std": {
                "pattern": "^(?<timestamp>\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}) (?<unused_cap>\\w+) (?<body>.*)$"
            }
        },
        "sample": [
            { "line": "2023-01-01 12:00:00 INFO hello" }
        ]
    }
}
EOF
echo "###### -I warndir -C (no -W)"; timeout 20 /workspace/executable -I /tmp/lnav-mgmt-9x7q/warndir -C > o.out 2> o.err; echo "EXIT=$?"; echo "--stdout--"; cat o.out; echo "--stderr--"; cat o.err; echo "###### -I warndir -W -C"; timeout 20 /workspace/executable -I /tmp/lnav-mgmt-9x7q/warndir -W -C > o.out 2> o.err; echo "EXIT=$?"; echo "--stdout--"; cat o.out; echo "--stderr--"; cat o.err

cd /tmp/lnav-mgmt-9x7q && cat > mytheme.json <<'EOF'
{
    "$schema": "https://lnav.org/schemas/config-v1.schema.json",
    "ui": {
        "theme-defs": {
            "probe-theme": {
                "vars": { "black": "#000000" },
                "styles": { "text": { "color": "#c0c0c0", "background-color": "#000000" } }
            }
        }
    }
}
EOF
echo "###### -i mytheme.json"; timeout 20 /workspace/executable -i /tmp/lnav-mgmt-9x7q/mytheme.json > o.out 2> o.err; echo "EXIT=$?"; echo "--stdout--"; cat o.out; echo "--stderr--"; cat o.err; ls -la ~/.lnav/configs/installed/
